def prompt(char, refs, body):
    return ' '.join(x for x in (LEAD, REF if refs else '', body, END) if x)
if __name__ == '__main__':
    acts = {**{n: 'r4v1' for n in range(1, 12)}, 12: 'r4ch', 13: 'r4ch', **{n: 'r4v2' for n in range(14, 22)}, 22: 'r4raid', 23: 'r4raid', **{n: 'r4v3' for n in range(24, 31)}, **{n: 'r4end' for n in range(31, 34)}}
    jobs = []
    for n, char, refs, body in S:
        p = prompt(char, refs, body)
        jobs.append({'n': n, 'id': f'B{n:02d}', 'character': char, 'refs': [f'{C}/{r}.jpg' for r in refs], 'prompt': p, 'words': len(p.split())})
